-- Datos de prueba para los reportes inteligentes (PN1 y PN2), generados con una semilla fija.
-- Cubren del 01/09/2025 al 12/11/2026: personas, vehiculos, cotizaciones, reservas, facturas con sus pagos,
-- y compras en todas sus etapas con inspeccion, tasaciones, forma de pago, documentos, pagos y comprobante.
-- Todos los Id empiezan con DA7A: DatosPrueba_Borrar.sql los quita sin tocar el resto.
-- Las filas quedan con el DVH pendiente (64 ceros): despues hay que sellarlas y rehacer el DVV con dv_sellar.ps1.
-- Las altas de Vehiculo disparan TR_Vehiculo_Alta, que deja su fila en BitacoraCambios.
SET QUOTED_IDENTIFIER ON
SET NOCOUNT ON
SET XACT_ABORT ON
GO

IF EXISTS (SELECT * FROM dbo.Persona WHERE CAST(Persona_Id AS char(36)) LIKE 'DA7A%')
BEGIN
    RAISERROR('Los datos de prueba ya estan cargados. Ejecute DatosPrueba_Borrar.sql antes de volver a cargarlos.', 16, 1)
    SET NOEXEC ON
END
GO

